<script setup lang="ts">import type{DebtBucket,HighDebtItem}from '@/types/dashboard';defineProps<{buckets:DebtBucket[];items:HighDebtItem[];loading:boolean}>();const emit=defineEmits<{collect:[id:number];detail:[id:number];print:[id:number]}>();const money=(v:number)=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(v)</script>
<template><v-card border rounded="xl"><div class="pa-4 pa-md-5"><div class="text-h6 font-weight-bold">Tình hình công nợ</div><div class="text-caption text-medium-emphasis">Phân nhóm tuổi nợ và các hộ cần ưu tiên xử lý</div><v-row class="mt-2"><v-col v-for="(bucket,index) in buckets" :key="bucket.key" cols="6" md="3"><div class="debt-bucket" :class="`debt-bucket--${index}`"><span>{{ bucket.label }}</span><strong>{{ bucket.households }} hộ</strong><small>{{ money(bucket.amount) }}</small></div></v-col></v-row></div><v-divider /><v-data-table :headers="[{title:'Mã hộ',key:'code'},{title:'Chủ hộ',key:'owner_name'},{title:'Tuyến',key:'route_name'},{title:'Thu gần nhất',key:'last_paid_month'},{title:'Số tháng nợ',key:'debt_months'},{title:'Tổng nợ',key:'total_debt',align:'end'},{title:'Thao tác',key:'actions',align:'end',sortable:false}]" :items="items" :loading="loading" density="comfortable" hover items-per-page="5"><template #item.last_paid_month="{value}">{{ value||'Chưa thu' }}</template><template #item.debt_months="{value}"><v-chip :color="value>12?'error':value>6?'warning':'info'" size="small" variant="tonal">{{ value }} tháng</v-chip></template><template #item.total_debt="{value}"><strong class="text-error text-no-wrap">{{ money(value) }}</strong></template><template #item.actions="{item}"><v-menu><template #activator="{props}"><v-btn v-bind="props" icon="mdi-dots-vertical" size="small" variant="text" /></template><v-list density="compact"><v-list-item prepend-icon="mdi-eye-outline" title="Xem chi tiết" @click="emit('detail',(item as any).household_id)"/><v-list-item prepend-icon="mdi-cash-register" title="Thu phí" @click="emit('collect',(item as any).household_id)"/><v-list-item prepend-icon="mdi-printer-outline" title="In thông báo nợ" @click="emit('print',(item as any).household_id)"/></v-list></v-menu></template><template #no-data><div class="empty-state">Không có hộ còn công nợ</div></template></v-data-table></v-card></template>
